struct DynArr {
    int* data;
    int size;
    int cap;
};

void init(DynArr& d) {
    d.cap = 4;
    d.size = 0;
    d.data = new int[d.cap];
}

void push(DynArr& d, int x) {
    if (d.size == d.cap) {
        int* bigger = new int[d.cap * 2];
        for (int i = 0; i < d.size; i++) bigger[i] = d.data[i];
        delete[] d.data;
        d.data = bigger;
        d.cap *= 2;
    }
    d.data[d.size++] = x;
}

int main() {
