    init(d);
    int x;
    while (cin >> x) push(d, x);
    cout << d.size << "\n";
    for (int i = d.size - 1; i >= 0; i--) cout << d.data[i] << " ";
    cout << "\n";
    delete[] d.data;
    return 0;
}

